const Predictor&
GetPredictor(PredictionStage stage)
{
    switch (stage)
    {
    case PredictionStage::T0:
        return g_t0Predictor;
    case PredictionStage::T1:
        return g_t1Predictor;
    case PredictionStage::T2:
        return g_t2Predictor;
    case PredictionStage::T4:
        return g_t4Predictor;
    }
    throw std::invalid_argument("unknown prediction stage");
}

